To create a CSV downloader using web workers in Ember Octane, follow these steps:

1. Install the necessary dependencies:

```bash
ember install ember-cli-htmlbars
ember install ember-cli-json-api
ember install ember-cli-web-worker
```

2. Create a new service for handling the CSV download:

```bash
touch app/services/csv-downloader.js
```

3. Implement the CSV downloader service:

```javascript
import Service from '@ember/service';
import { inject as service } from '@ember/service';
import { A } from '@ember/array';
import { read } from 'ember-cli-json-api';
import { task } from 'ember-concurrency';
import CSVBuilder from 'csv-builder';
import { worker } from 'ember-cli-web-worker';

export default class CsvDownloaderService extends Service {
  @service store;

  @task
  *downloadCSV(queryParams) {
    const { resourceType, filter } = queryParams;

    const records = yield read(`${resourceType}`, {
      queryParams: {
        filter,
      },
    });

    const csvBuilder = new CSVBuilder();
    const headers = records[0] && Object.keys(records[0]);
    const rows = records.map((record) => headers.map((header) => record[header]));

    const csv = csvBuilder.csvByRow(A(rows));

    this._super.get('downloadCSVTask').cancelAll();
    this._super.get('downloadCSVTask').perform(csv);
  }

  @worker
  *downloadCSVTask(csv) {
    const blob = new Blob([csv], { type: 'text/csv' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    link.download = `${this._super.get('resourceType')}.csv`;
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  }
}
```

4. Update the `app/router/application.js` to inject the CSV downloader service:

